#!/usr/bin/env python3\n\"\"\"Teste rapido do padronizador de deltas.\"\"\"\nimport sys\nimport os\nimport json\n\n# Adiciona o diretorio ao path\nsys.path.insert(0, os.path.dirname(__file__))\n\nimport memoria_delta_gui as m\nfrom pathlib import Path\n\n# Conteudo real do arquivo do usuario\ntest_content = r\"\"\"{\n  \"data\": \"2026-05-09\",\n  \"ADD\": [\n    {\n      \"tag\": \"INFO\",\n      \"text\": \"CPU Ryzen 9 9900X: limite térmico 85°C configurado (clima 30°C).\"\n    }\n  ],\n  \"UPDATE\": {},\n  \"REMOVE\": [],\n  \"CONTEXTO_RECENTE\": \"Configurado thermal limit 85°C no Ryzen 9 9900X; mitigação de calor ambiente (30°C) via throttling preventivo.\"\n}\n\n{\n  \"data\": \"2026-05-10\",\n  \"ADD\": [\n    {\n      \"tag\": \"INFO\",\n      \"text\": \"CPU Ryzen 9 10900X: limite térmico 85°C configurado (clima 30°C).\"\n    }\n  ],\n  \"UPDATE\": {},\n  \"REMOVE\": [],\n  \"CONTEXTO_RECENTE\": \"Configurado thermal limit 85°C no Ryzen 9 9900X; mitigação de calor ambiente (30°C) via throttling preventivo.\"\n}\n\n## ESTADO_ATUAL\n\n### 2026-05-09\n- [INFO] CPU Ryzen 9 9900X: limite térmico 85°C configurado.\n\"\"\"\n\n# Escreve arquivo de teste\ntest_file = Path(\"/tmp/test_memoria.md\")\ntest_file.write_text(test_content, encoding=\"utf-8\")\n\n# Extrai deltas\ndc = m.DeltaCollector(test_file)\ndeltas = dc.extract_pending_deltas()\n\nprint(f\"Deltas extraidos: {len(deltas)}\")\nif deltas:\n    for i, d in enumerate(deltas):\n        print(f\"  Delta {i+1}: data={d.get('data')}, ADD={len(d.get('ADD', []))}, UPDATE={len(d.get('UPDATE', {}))}, REMOVE={len(d.get('REMOVE', []))}\")\nelse:\n    print(\"ERRO: Nenhum delta extraido!\")\n    sys.exit(1)\n\n# Testa limpeza\ncleaned = m.DeltaCollector.clean_pending_deltas(test_content)\nprint(f\"Limpeza OK: {len(deltas)} blocos JSON removidos\")\nprint(f\"Estado atual permanece: {'## ESTADO_ATUAL' in cleaned}\")\n\n# Remove arquivo de teste\ntest_file.unlink()\nprint(\"\\nTestes passaram!\")\n\n
